//! Ferret: CRC-16, implemented in Rust.
//!
//! Replaces `lib/crc/crc16.c`. The C ABI (`include/linux/crc16.h`) is
//! unchanged:
//!
//! ```c
//! u16 crc16(u16 crc, const u8 *p, size_t len);
//! ```
//!
//! Model: width 16, poly 0x8005 (x^16 + x^15 + x^2 + 1), reflected input and
//! output (table-driven, LSB-first), init passed by the caller, no final XOR.
//! This is CRC-16/ARC with a caller-supplied initial value.

use kernel::prelude::*;

/// Byte lookup table for the reflected 0x8005 polynomial.
///
/// Generated by the same construction as the C original
/// (`crc16_table[i]` is the CRC of byte `i` with initial value 0), so the
/// values are byte-for-byte identical to `lib/crc/crc16.c`.
