/// Compute the CRC-16 for a data buffer.
///
/// # Safety
///
/// `p` must be valid for reads of `len` bytes, or `len` must be zero (in
/// which case `p` is never dereferenced and may be null, matching the C
/// contract).
///
/// # Arguments
///
/// * `crc` - previous CRC value (0 for a fresh computation)
/// * `p`   - data pointer
/// * `len` - number of bytes in the buffer
#[export]
pub unsafe extern "C" fn crc16(mut crc: u16, p: *const u8, len: usize) -> u16 {
    let mut remaining = len;
    let mut data = p;

    while remaining > 0 {
        // SAFETY: `data` is valid for reads of `remaining` bytes (precondition)
        // and `remaining > 0`, so this read is in bounds. The pointer is
        // advanced by one byte per iteration and `remaining` is decremented in
        // lockstep.
        let byte = unsafe { *data };
        let index = ((crc & 0xff) as usize) ^ (byte as usize);
        // SAFETY: `index` is the XOR of a value in 0..=255 and a u8, therefore
        // always in 0..=255, and the table has 256 entries. Using
        // `get_unchecked` keeps the exported path free of bounds-check panics.
        crc = (crc >> 8) ^ unsafe { *CRC16_TABLE.get_unchecked(index) };
        // SAFETY: one-past-the-end of the current byte is still within the
        // caller-provided buffer because `remaining` bytes remain before the
        // decrement below.
        data = unsafe { data.add(1) };
        remaining -= 1;
    }

    crc
}

#[cfg(CONFIG_KUNIT)]
#[kunit_tests(crc16_rust)]
mod tests {
    use super::crc16;

    /// CRC-16/ARC check value: "123456789" with init 0 -> 0xBB3D.
    #[test]
    fn crc16_rust_check_value() {
        let data = b"123456789";
        // SAFETY: valid slice pointer and length.
        let out = unsafe { crc16(0, data.as_ptr(), data.len()) };
        assert_eq!(out, 0xbb3d);
    }

    #[test]
    fn crc16_rust_empty_buffer() {
        // Zero length: the pointer is never dereferenced, even if null.
        // SAFETY: len == 0, so the null pointer is not read.
        let out = unsafe { crc16(0x1234, core::ptr::null(), 0) };
        assert_eq!(out, 0x1234);
    }

    #[test]
    fn crc16_rust_incremental() {
        let data = b"Ferret rewrites the Linux kernel in Rust, one component at a time.";
        let split = 13;
        // SAFETY: pointers are derived from `data` with in-bounds lengths.
        let whole = unsafe { crc16(0, data.as_ptr(), data.len()) };
        // SAFETY: as above.
        let first = unsafe { crc16(0, data.as_ptr(), split) };
        // SAFETY: as above.
        let rest = unsafe { crc16(first, data.as_ptr().add(split), data.len() - split) };
        assert_eq!(whole, rest);
    }

    #[test]
    fn crc16_rust_all_initial_values_single_byte() {
        let byte = [0xa5u8];
        let mut init = 0u32;
        while init < 0x10000 {
            // SAFETY: valid slice pointer and length 1.
            let out = unsafe { crc16(init as u16, byte.as_ptr(), 1) };
            let expected = (((init as u16) >> 8)
                ^ crate::CRC16_TABLE[(((init as u16) & 0xff) as usize) ^ 0xa5])
                & 0xffff;
            assert_eq!(out, expected);
            init += 1;
        }
    }

    #[test]
    fn crc16_rust_deterministic_prng() {
        // xorshift32: deterministic pseudo-random stream, no allocation.
        let mut state = 0x2545_f491u32;
        let mut buf = [0u8; 257];
        buf[0] = 0x5a;
        let mut i = 1;
        while i < buf.len() {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            buf[i] = (state >> 24) as u8;
            i += 1;
        }
        // Reference: bit-at-a-time CRC-16/ARC, independent of the table code.
        let mut crc: u16 = 0x1d0f;
        for &b in buf.iter() {
            crc ^= b as u16;
            let mut bit = 0;
            while bit < 8 {
                if crc & 1 != 0 {
                    crc = (crc >> 1) ^ 0xa001;
                } else {
                    crc >>= 1;
                }
                bit += 1;
            }
        }
        // SAFETY: valid slice pointer and length.
        let out = unsafe { crc16(0x1d0f, buf.as_ptr(), buf.len()) };
        assert_eq!(out, crc);
    }
}
